from pathlib import Path
import re

root = Path('/home/ubuntu/rainha-das-capas')

(root / 'client/src/lib/firebase.ts').write_text('''import { getApp, getApps, initializeApp } from "firebase/app";\nimport { getAuth } from "firebase/auth";\nimport { getFirestore } from "firebase/firestore";\n\nconst firebaseConfig = {\n  apiKey: import.meta.env.VITE_FIREBASE_API_KEY,\n  authDomain: import.meta.env.VITE_FIREBASE_AUTH_DOMAIN,\n  projectId: import.meta.env.VITE_FIREBASE_PROJECT_ID,\n  storageBucket: import.meta.env.VITE_FIREBASE_STORAGE_BUCKET,\n  messagingSenderId: import.meta.env.VITE_FIREBASE_MESSAGING_SENDER_ID,\n  appId: import.meta.env.VITE_FIREBASE_APP_ID,\n  measurementId: import.meta.env.VITE_FIREBASE_MEASUREMENT_ID,\n};\n\nexport const firebaseApp = getApps().length ? getApp() : initializeApp(firebaseConfig);\nexport const firebaseAuth = getAuth(firebaseApp);\nexport const firestore = getFirestore(firebaseApp);\n''')

(root / 'client/src/lib/sharedWorkspace.ts').write_text('''import { signInAnonymously, onAuthStateChanged, type User } from "firebase/auth";\nimport { doc, onSnapshot, setDoc } from "firebase/firestore";\nimport { useCallback, useEffect, useState } from "react";\nimport { firebaseAuth, firestore } from "./firebase";\n\nexport type SharedSellerItem = { clientId?: string; item: string; quantity: number; unit: string; total: string; date: string; note: string };\nexport type SharedSeller = { clientId?: string; name: string; initials: string; phone: string; total: string; status: string; updated: string; tone: string; avatar?: string; items?: SharedSellerItem[] };\nexport type SharedCatalogStore = { id: string; name: string; categories: Array<{ id: string; name: string; subcategories: Array<{ id: string; name: string; items: Array<{ id: string; name: string }> }> }> };\n\nexport function useAnonymousSession() {\n  const [user, setUser] = useState<User | null>(firebaseAuth.currentUser);\n  const [loading, setLoading] = useState(!firebaseAuth.currentUser);\n  const [error, setError] = useState<string | null>(null);\n  useEffect(() => {\n    const unsubscribe = onAuthStateChanged(firebaseAuth, (next) => { setUser(next); setLoading(false); });\n    if (!firebaseAuth.currentUser) signInAnonymously(firebaseAuth).catch((err: unknown) => { setError(err instanceof Error ? err.message : "Ative o login anônimo no Firebase"); setLoading(false); });\n    return unsubscribe;\n  }, []);\n  return { user, loading, error };\n}\n\nexport function useSharedWorkspace(seedSellers: SharedSeller[], seedCatalog: SharedCatalogStore[]) {\n  const [sellers, setSellers] = useState(seedSellers);\n  const [catalog, setCatalog] = useState(seedCatalog);\n  const [ready, setReady] = useState(false);\n  const session = useAnonymousSession();\n  const ref = doc(firestore, "sharedWorkspaces", "main");\n  useEffect(() => {\n    if (!session.user) return;\n    return onSnapshot(ref, (snapshot) => {\n      const data = snapshot.data() as { sellers?: SharedSeller[]; catalog?: SharedCatalogStore[] } | undefined;\n      if (data?.sellers) setSellers(data.sellers);\n      if (data?.catalog) setCatalog(data.catalog);\n      if (!snapshot.exists()) void setDoc(ref, { sellers: seedSellers, catalog: seedCatalog, updatedAt: Date.now() });\n      setReady(true);\n    }, () => setReady(true));\n  }, [session.user, ref, seedSellers, seedCatalog]);\n  const persist = useCallback(async (nextSellers: SharedSeller[], nextCatalog: SharedCatalogStore[]) => {\n    await setDoc(ref, { sellers: nextSellers, catalog: nextCatalog, updatedAt: Date.now() }, { merge: true });\n  }, [ref]);\n  useEffect(() => { if (ready && session.user) void persist(sellers, catalog); }, [ready, session.user, sellers, catalog, persist]);\n  return { sellers, setSellers, catalog, setCatalog, ready, session };\n}\n''')

path = root / 'client/src/pages/Home.tsx'
text = path.read_text()
text = text.replace('import { useAuth } from "@/_core/hooks/useAuth";\n', '')
text = text.replace('import { startLogin } from "@/const";\n', '')
text = text.replace('import { trpc } from "@/lib/trpc";\n', '')
text = text.replace('import { createOperationId, enqueueOfflineAction, readOfflineQueue, removeOfflineAction } from "@/lib/offlineQueue";\n', '')
text = text.replace('import { cropAndCompressProfileImage } from "@/lib/profileImage";\n', '')
text = text.replace('import { toast } from "sonner";\n', 'import { toast } from "sonner";\nimport { useAnonymousSession, useSharedWorkspace, type SharedSeller, type SharedCatalogStore } from "@/lib/sharedWorkspace";\n')
text = text.replace('type SellerItem = {', 'type SellerItem = {')
text = text.replace('function LoginScreen() {\n  return <div className="auth-screen"><div className="auth-card"><div className="auth-logo"><img src={logo} alt="Rainha das Capas" /></div><span className="eyebrow">RAINHA DAS CAPAS · ACESSO RESTRITO</span><h1>Entre na sua operação.</h1><p>Use sua conta Google para acessar o painel comercial com segurança.</p><button className="gold-button auth-login" onClick={() => startLogin()}><ShieldCheck size={16} /> Entrar com Google</button><small>O acesso é protegido pelo portal oficial de autenticação.</small></div></div>;\n}\n', '')

start = text.index('function ProfileModule(')
end = text.index('function UsersModule(', start)
profile = '''function ProfileModule({ profileName, onSaved }: { profileName: string; onSaved: (name: string) => void }) {\n  const [draftName, setDraftName] = useState(profileName);\n  return <div className="page-stack page-enter"><div className="page-title-row"><div><span className="eyebrow">IDENTIDADE LOCAL</span><h1>Perfil</h1><p>Defina o nome que será exibido neste navegador. Não há login ou conta pessoal.</p></div><span className="admin-badge"><ShieldCheck size={15} /> Acesso compartilhado</span></div><article className="panel profile-card"><span className="eyebrow">DADOS DO COLABORADOR</span><label className="profile-name-field">Nome exibido<input value={draftName} onChange={(event) => setDraftName(event.target.value)} placeholder="Seu nome" /></label><p className="profile-email">Identificação anônima do dispositivo</p><button className="gold-button profile-save-button" onClick={() => { if (!draftName.trim()) return; onSaved(draftName.trim()); toast.success("Nome salvo neste dispositivo"); }}>Salvar nome</button></article></div>;\n}\n\n'''
text = text[:start] + profile + text[end:]

home_start = text.index('export default function Home() {')
# Preserve everything before Home and replace the full Home shell with a compact Firestore-backed shell.
new_home = '''export default function Home() {\n  const [active, setActive] = useState("dashboard");\n  const [selectedSeller, setSelectedSeller] = useState<Seller | null>(null);\n  const [sidebarOpen, setSidebarOpen] = useState(() => typeof window === "undefined" || window.innerWidth > 760);\n  const touchStartX = useRef<number | null>(null);\n  const [profileName, setProfileName] = useState(() => localStorage.getItem("rainha-profile-name") || "Visitante");\n  const [accountOpen, setAccountOpen] = useState(false);\n  const [darkMode, setDarkMode] = useState(false);\n  const [installPrompt, setInstallPrompt] = useState<InstallPromptEvent | null>(null);\n  const seedSellerData = useMemo(() => sellers as SharedSeller[], []);\n  const seedCatalogData = useMemo(() => catalogSeed as SharedCatalogStore[], []);\n  const workspace = useSharedWorkspace(seedSellerData, seedCatalogData);\n  const sellerList = workspace.sellers as Seller[];\n  const catalogStores = workspace.catalog as CatalogStore[];\n  const session = workspace.session;\n  const [isOnline, setIsOnline] = useState(() => typeof navigator === "undefined" ? true : navigator.onLine);\n  useEffect(() => { const online = () => setIsOnline(true); const offline = () => setIsOnline(false); window.addEventListener("online", online); window.addEventListener("offline", offline); return () => { window.removeEventListener("online", online); window.removeEventListener("offline", offline); }; }, []);\n  useEffect(() => { const onInstall = (event: Event) => { event.preventDefault(); setInstallPrompt(event as InstallPromptEvent); }; window.addEventListener("beforeinstallprompt", onInstall); return () => window.removeEventListener("beforeinstallprompt", onInstall); }, []);\n  const installApp = async () => { if (!installPrompt) return; await installPrompt.prompt(); await installPrompt.userChoice; setInstallPrompt(null); };\n  const navigate = (id: string) => { setSelectedSeller(null); setActive(id); if (typeof window !== "undefined" && window.innerWidth <= 760) setSidebarOpen(false); };\n  const handleSidebarTouchStart = (event: TouchEvent<HTMLElement>) => { touchStartX.current = event.changedTouches[0]?.clientX ?? null; };\n  const handleSidebarTouchEnd = (event: TouchEvent<HTMLElement>) => { const start = touchStartX.current; const end = event.changedTouches[0]?.clientX ?? null; touchStartX.current = null; if (start !== null && end !== null && start - end > 55) setSidebarOpen(false); };\n  const recordActivity = (action: string) => { toast.success(action); };\n  const setSellers = (next: Seller[] | ((current: Seller[]) => Seller[])) => workspace.setSellers((current) => (typeof next === "function" ? next(current as Seller[]) : next) as SharedSeller[]);\n  const setCatalog = (next: CatalogStore[] | ((current: CatalogStore[]) => CatalogStore[])) => workspace.setCatalog((current) => (typeof next === "function" ? next(current as CatalogStore[]) : next) as SharedCatalogStore[]);\n  const addSeller = (seller: Seller) => { const next = { ...seller, clientId: seller.clientId ?? `seller-${Date.now()}` }; setSellers((current) => [...current, next]); recordActivity("Revendedor compartilhado"); };\n  const addItem = (item: SellerItem) => { if (!selectedSeller) return; const nextItem = { ...item, clientId: item.clientId ?? `item-${Date.now()}` }; const items = [...(selectedSeller.items ?? []), nextItem]; const next = { ...selectedSeller, items, total: currency(items.reduce((sum, row) => sum + moneyNumber(row.total), 0)), updated: "Agora" }; setSellers((current) => current.map((seller) => seller.clientId === next.clientId ? next : seller)); setSelectedSeller(next); recordActivity("Item compartilhado"); };\n  const deleteSeller = (seller: Seller) => { setSellers((current) => current.filter((item) => item.clientId !== seller.clientId)); setSelectedSeller(null); recordActivity("Revendedor removido"); };\n  const updateStatus = (seller: Seller, status: string) => { const next = { ...seller, status, tone: status === "Pago" ? "success" : status === "Acordo" ? "warning" : "danger", updated: "Agora" }; setSellers((current) => current.map((item) => item.clientId === seller.clientId ? next : item)); if (selectedSeller?.clientId === seller.clientId) setSelectedSeller(next); recordActivity("Pagamento atualizado"); };\n  const deleteItem = (item: SellerItem) => { if (!selectedSeller) return; const items = (selectedSeller.items ?? []).filter((row) => row.clientId !== item.clientId); const next = { ...selectedSeller, items, total: currency(items.reduce((sum, row) => sum + moneyNumber(row.total), 0)), updated: "Agora" }; setSellers((current) => current.map((seller) => seller.clientId === next.clientId ? next : seller)); setSelectedSeller(next); recordActivity("Item removido"); };\n  const activeLabel = selectedSeller ? selectedSeller.name : formatTitle(active);\n  if (session.loading || !workspace.ready) return <div className="auth-screen"><div className="auth-card auth-loading"><Activity className="spin" size={24} /><span>Conectando ao espaço compartilhado...</span></div></div>;\n  if (session.error) return <div className="auth-screen"><div className="auth-card"><h1>Ative o acesso compartilhado</h1><p>Habilite o provedor Anonymous em Firebase Authentication para continuar.</p><small>{session.error}</small></div></div>;\n  return <div className={`app-shell ${sidebarOpen ? "sidebar-open" : "sidebar-collapsed"} ${darkMode ? "theme-dark" : ""}`}>\n    {sidebarOpen && <button className="mobile-overlay" aria-label="Fechar menu" onClick={() => setSidebarOpen(false)} />}<aside className="sidebar" onTouchStart={handleSidebarTouchStart} onTouchEnd={handleSidebarTouchEnd}><div className="brand"><div className="brand-mark"><img src={logo} alt="" /></div><div><strong>RAINHA</strong><span>DAS CAPAS</span></div></div><div className="workspace-switcher"><div className="store-mark"><Store size={15} /></div><div><strong>Operação compartilhada</strong><small>FireStore · acesso anônimo</small></div><ChevronDown size={14} /></div><nav className="main-nav"><span className="nav-caption">MENU PRINCIPAL</span>{navItems.filter(({ id }) => id !== "usuarios" && id !== "perfil").map(({ id, label, icon: Icon }) => <button key={id} className={active === id && !selectedSeller ? "active" : ""} onClick={() => navigate(id)}><Icon size={18} /><span>{label}</span></button>)}<button className={active === "perfil" && !selectedSeller ? "active" : ""} onClick={() => navigate("perfil")}><UserRound size={18} /><span>Perfil local</span></button></nav><div className="sidebar-bottom"><button className="profile-button" onClick={() => setAccountOpen((value) => !value)} title="Abrir menu da conta"><div className="avatar tiny">{initialsFor(profileName)}</div><span><strong>{profileName}</strong><small>Acesso compartilhado</small></span><MoreHorizontal size={16} /></button>{accountOpen && <div className="account-menu"><button onClick={() => { navigate("perfil"); setAccountOpen(false); }}><UserRound size={15} /> Meu perfil</button></div>}</div></aside>\n    <main className="main-area"><header className="topbar"><div className="topbar-left"><button className="mobile-menu" onClick={() => setSidebarOpen((v) => !v)}><Menu size={19} /></button><button className="collapse-button" onClick={() => setSidebarOpen((v) => !v)}>{sidebarOpen ? <PanelLeftClose size={18} /> : <PanelLeftOpen size={18} />}</button><div className="breadcrumb"><span>Rainha das Capas</span><ChevronRight size={14} /><strong>{activeLabel}</strong></div></div><div className="topbar-right"><span className={`connection-status ${isOnline ? "online" : "offline"}`} title={isOnline ? "Conectado" : "Sem conexão"}><Wifi size={14} /></span>{installPrompt && <button className="install-pwa-button" onClick={() => void installApp()} title="Instalar aplicativo"><Download size={16} /> <span>Instalar</span></button>}<button className="topbar-icon"><Search size={18} /></button><button className="topbar-icon notification"><Bell size={18} /><i /></button><div className="top-avatar">{initialsFor(profileName)}</div></div></header><div className="content-area">{selectedSeller ? <SellerDetail seller={selectedSeller} onBack={() => setSelectedSeller(null)} onAddItem={addItem} onDeleteItem={deleteItem} /> : active === "dashboard" ? <Dashboard sellers={sellerList} onNavigate={navigate} /> : active === "revendedores" ? <Revendedores sellers={sellerList} onSelect={setSelectedSeller} onAdd={addSeller} onDelete={deleteSeller} /> : active === "pagamentos" ? <Payments sellers={sellerList} onStatusChange={updateStatus} /> : active === "relatorios" ? <ReportsModule sellers={sellerList} /> : active === "mercadorias" ? <MercadoriasModule stores={catalogStores} onChange={setCatalog} /> : active === "semanas" ? <WeeksModule sellers={sellerList} /> : active === "perfil" ? <ProfileModule profileName={profileName} onSaved={(name) => { setProfileName(name); localStorage.setItem("rainha-profile-name", name); }} /> : <GenericModule id={active} />}</div><footer className="app-footer"><span>Rainha das Capas · Gestão Comercial</span><span>Espaço compartilhado em tempo real</span></footer></main>\n  </div>;\n}\n'''
text = text[:home_start] + new_home
path.write_text(text)
